// VideoServiceHandler is an implementation of the gcs.v1.VideoService service.
type VideoServiceHandler interface {
	// WatchStreams streams VideoStreamEvents as streams appear, change state, or end.
	// Immediately emits STREAM_APPEARED for each currently active stream on subscribe.
	WatchStreams(context.Context, *connect.Request[v1.WatchStreamsRequest], *connect.ServerStream[v1.VideoStreamEvent]) error
	// ExchangeSdp performs the WebRTC offer/answer handshake for a WEBRTC stream.
	// The frontend sends an SDP offer; the backend (GCS media server) returns an SDP answer.
	// ICE candidates are included inline (trickle ICE not supported in this version).
	ExchangeSdp(context.Context, *connect.Request[v1.SdpOffer]) (*connect.Response[v1.SdpAnswer], error)
	// StartRecording begins recording a stream to persistent storage.
	StartRecording(context.Context, *connect.Request[v1.StartRecordingRequest]) (*connect.Response[v1.StartRecordingResponse], error)
	// StopRecording ends an active recording and returns the completed metadata.
	StopRecording(context.Context, *connect.Request[v1.StopRecordingRequest]) (*connect.Response[v1.StopRecordingResponse], error)
	// ListRecordings returns stored recordings filtered by node or time range.
	ListRecordings(context.Context, *connect.Request[v1.ListRecordingsRequest]) (*connect.Response[v1.ListRecordingsResponse], error)
}

